285			t.Fatalf("changed-content retry must not return a failed job posing as accepted: %+v", got)
286		}
287		done := waitStatus(t, s2, got.ID, StatusSucceeded)
288		// 必须按新内容接受：种子 9、无依赖、实际输入只有 [4]，绝不沿用被拒绝
289		// 请求的 [2,-3] 或对上游总和 5 的依赖。
290		if done.Seed != 9 || done.RequestID != "change-k" {
291			t.Fatalf("accepted retry params wrong: %+v", done)
292		}
293		if len(done.Dependencies) != 0 || done.HasDependency || done.DependencyID != 0 {
294			t.Fatalf("accepted retry must carry no dependency from rejected request: %+v", done)
295		}
296		if len(done.Values) != 1 || done.Values[0] != 4 {
297			t.Fatalf("accepted retry original values=%v want [4]", done.Values)
298		}
299		if len(done.Archive.EffectiveValues) != 1 || done.Archive.EffectiveValues[0] != 4 {
300			t.Fatalf("accepted retry effective=%v want [4] (must not append upstream sum 5)",
301				done.Archive.EffectiveValues)
302		}
303		if done.Archive.Sum != 4 || done.Archive.SumOfSquares != 16 {
304			t.Fatalf("accepted retry results sum=%d sq=%d, want 4,16",
305				done.Archive.Sum, done.Archive.SumOfSquares)
306		}
307		assertUpstreamUnchanged(t, dir, s2, up, upDisk)
308	
309		// 同号请求真正被接受以后，现有幂等规则才生效：
310		// 相同内容再次提交返回该作业当前详情；改变内容返回冲突并保留原记录。
311		replay, err := s2.Submit(changed)
312		if err != nil || replay == nil || replay.ID != got.ID || replay.Status != StatusSucceeded {
313			t.Fatalf("idempotent replay after acceptance: job=%+v err=%v", replay, err)
314		}
315		conflictJob, err := s2.Submit(SubmitRequest{
316			Submitter: "alice", RequestID: "change-k",
317			Values: []int64{2, -3}, Seed: 7,
318			Dependencies: []uint64{up.ID},
319		})
320		if !errors.Is(err, ErrIdempotencyConflict) || conflictJob == nil || conflictJob.ID != got.ID {
321			t.Fatalf("changed content after acceptance must conflict: job=%+v err=%v", conflictJob, err)
322		}
323		kept := waitStatus(t, s2, got.ID, StatusSucceeded)
324		if kept.Archive.Sum != 4 || kept.Archive.SumOfSquares != 16 || kept.Seed != 9 ||
325			len(kept.Dependencies) != 0 || len(kept.Archive.EffectiveValues) != 1 {
326			t.Fatalf("accepted record must be preserved by conflict: %+v", kept)
327		}
328		assertUpstreamUnchanged(t, dir, s2, up, upDisk)
329	}
330	
331	// 已接受作业后来计算失败与“首份记录保存失败、请求未被接受”是两回事：
332	// 终态为失败的作业仍保留自己的作业号与请求号，相同内容重放返回它本身，
333	// 改变内容按冲突处理并保留失败记录——不能把失败终态当作允许重新创建作业
334	// 的理由（重开归档后同样如此）。
335	func TestAcceptedThenFailedJobKeepsIDAndRequestIDAcrossReplay(t *testing.T) {
336		dir := t.TempDir()
337		s, err := Open(dir)
338		if err != nil {
339			t.Fatal(err)
340		}
341		big := int64(3037000500)
342		req := SubmitRequest{Submitter: "a", RequestID: "k", Values: []int64{big}}
343		j := mustSubmit(t, s, req)
344		failed := waitStatus(t, s, j.ID, StatusFailed)
345		if !strings.Contains(failed.FailureReason, "平方和") || failed.Archive != nil {
346			t.Fatalf("accepted job should fail by overflow with no archive: %+v", failed)
347		}
348		if failed.ID != j.ID || failed.RequestID != "k" {
349			t.Fatalf("failed terminal job must keep own id and request id: %+v", failed)
350		}
351	
352		// 相同内容再次提交：返回该失败作业本身，无错误，不重建作业、不重新排队。
353		replay, err := s.Submit(req)
354		if err != nil || replay == nil || replay.ID != j.ID || replay.Status != StatusFailed {
355			t.Fatalf("replay of accepted-then-failed job must return the same job: %+v err=%v", replay, err)
356		}
357		// 改变内容：幂等冲突，同时返回原失败作业，原因保持不变。
358		cj, err := s.Submit(SubmitRequest{
359			Submitter: "a", RequestID: "k", Values: []int64{1, 2}, Seed: 0,
360		})
361		if !errors.Is(err, ErrIdempotencyConflict) || cj == nil || cj.ID != j.ID {
362			t.Fatalf("changed content for failed accepted job must conflict: %+v err=%v", cj, err)
363		}
364		if cj.Status != StatusFailed || cj.FailureReason != failed.FailureReason || cj.Archive != nil {
365			t.Fatalf("failed record altered by conflict attempt: %+v", cj)
366		}
367		if countJobFiles(t, dir) != 1 {
368			t.Fatalf("replay/conflict must not create records: %d files", countJobFiles(t, dir))
369		}
370	
371		// 重开归档后仍保留自己的作业号与请求号，重放依旧指向它，不允许重建。
372		if err := s.Close(); err != nil {
373			t.Fatal(err)
374		}
375		s2, err := Open(dir)
376		if err != nil {
377			t.Fatal(err)
378		}
379		defer s2.Close()
380		g, _ := s2.Get(j.ID)
381		if g.Status != StatusFailed || g.RequestID != "k" || g.FailureReason != failed.FailureReason {
382			t.Fatalf("failed accepted job after reopen: %+v", g)
383		}
384		r2, err := s2.Submit(req)
385		if err != nil || r2 == nil || r2.ID != j.ID || r2.Status != StatusFailed {
386			t.Fatalf("replay after reopen must keep the failed job, no recreation: %+v err=%v", r2, err)
387		}
388	}
