14	// 本文件覆盖“已恢复作业的原文件名恰好等于新作业将使用的默认文件名”这一
15	// 形态：读取规则接受任何 job- 开头、.json 结尾的合法记录，作业号由记录内容
16	// 识别，允许合法记录使用非默认文件名（文件名中的数字可以与真实作业号不同）。
17	// 例如目录中只有作业 1，它却保存在 job-...0002.json 中：归档正常打开，但
18	// 新请求拟分配的作业号为 2，若按默认命名落盘会原子替换掉作业 1 的已保存
19	// 记录。提交功能必须在产生任何记录之前拒绝这类新请求。
20	
21	// restoredOccupiedBase 是构造恢复记录时使用的固定时间。
22	var restoredOccupiedBase = time.Date(2026, 5, 1, 8, 0, 0, 0, time.UTC)
23	
24	// succeededRecordInFile 构造一份内容合法的成功作业记录（不写盘）。
25	func succeededRecordInFile(t *testing.T, id uint64, submitter, requestID string, values []int64, at time.Time) *storedJob {
26		t.Helper()
27		j := &storedJob{
28			id:              id,
29			submitter:       submitter,
30			requestID:       requestID,
31			values:          append([]int64(nil), values...),
32			queuedAt:        at,
33			finishedAt:      at.Add(time.Second),
34			status:          StatusSucceeded,
35			effectiveValues: append([]int64(nil), values...),
36		}
37		sum, sumSq, _, ok := computeResult(values, 0, nil)
38		if !ok {
39			t.Fatalf("test setup: values %v overflow", values)
40		}
41		j.archive = newArchive(j, values, sum, sumSq, j.finishedAt)
42		return j
43	}
