45	// assertSubmitBlockedByOccupiedFile 提交一次新请求并断言它被文件名占用错误
46	// 拒绝：返回空作业与非空错误，错误包装 ErrRecordFileNameOccupied，并明确
47	// 给出拟分配的新作业号、被占用的文件名与原归属作业号。
48	func assertSubmitBlockedByOccupiedFile(t *testing.T, s *Store, req SubmitRequest, newID, ownerID uint64, occupiedName string) {
49		t.Helper()
50		j, err := s.Submit(req)
51		if j != nil || err == nil {
52			t.Fatalf("文件名被另一作业占用时必须拒绝新请求：job=%+v err=%v", j, err)
53		}
54		if !errors.Is(err, ErrRecordFileNameOccupied) {
55			t.Fatalf("错误必须包装 ErrRecordFileNameOccupied，got %v", err)
56		}
57		msg := err.Error()
58		for _, want := range []string{
59			jobFileName(newID), occupiedName, "另一作业 " + strconv.FormatUint(ownerID, 10),
60		} {
61			if !strings.Contains(msg, want) {
62				t.Fatalf("错误必须说明拟分配作业号、被占用文件名与原归属作业号（缺少 %q）：%v", want, err)
63			}
64		}
65	}
66	
67	// assertNewRequestLeftNoTrace 断言被拒绝的新请求没有留下任何痕迹：作业号未
68	// 消耗、请求号未登记、按作业号查询与按提交人列举都看不到、目录里没有新增
69	// 正式记录或临时文件，占用默认文件名的旧记录内容仍归属 ownerID。
70	func assertNewRequestLeftNoTrace(t *testing.T, s *Store, dir string, req SubmitRequest, rejectedID, ownerID uint64, wantFiles int) {
71		t.Helper()
72		if _, err := s.Get(rejectedID); !errors.Is(err, ErrNotFound) {
73			t.Fatalf("被拒绝请求不应能按作业号查询：%v", err)
74		}
75		list, err := s.List(req.Submitter, time.Time{}, time.Time{})
76		if err != nil {
77			t.Fatal(err)
78		}
79		for _, j := range list {
80			if j.ID == rejectedID {
81				t.Fatalf("被拒绝请求不应出现在按提交人列举中：%v", ids(list))
82			}
83		}
84		// 默认命名文件作为占用者存在，但其中的记录必须仍归属 ownerID：拒绝不得
85		// 用新作业的记录替换它。
86		data, err := os.ReadFile(filepath.Join(dir, jobFileName(rejectedID)))
87		if err != nil {
88			t.Fatal(err)
89		}
90		var onDisk jobRecord
91		if err := json.Unmarshal(data, &onDisk); err != nil {
92			t.Fatalf("占用文件记录损坏: %v", err)
93		}
94		if onDisk.ID != ownerID {
95			t.Fatalf("占用文件应仍归属作业 %d，却保存了作业 %d", ownerID, onDisk.ID)
96		}
97		if got := countJobFiles(t, dir); got != wantFiles {
98			t.Fatalf("目录中的正式记录数变化：got %d want %d", got, wantFiles)
99		}
100		if got := countTmpFiles(t, dir); got != 0 {
101			t.Fatalf("被拒绝请求不得残留临时文件：%d", got)
102		}
103		s.mu.Lock()
104		nextID := s.nextID
105		_, claimed := s.idem[idemIdentity{req.Submitter, req.RequestID}]
106		running := s.runningID
107		s.mu.Unlock()
108		if nextID != rejectedID {
109			t.Fatalf("拒绝不得消耗作业号：nextID=%d want %d", nextID, rejectedID)
110		}
111		if claimed {
112			t.Fatalf("拒绝不得登记提交人的请求号 %q", req.RequestID)
113		}
114		if running == rejectedID {
115			t.Fatal("被拒绝请求不得进入计算队列")
116		}
117	}
