119	// TestSubmitRejectsWhenDefaultRecordFileNameOccupied 核心场景：目录中只有
120	// 作业 1（成功归档），却保存在作业 2 的默认命名文件中。归档正常打开，但新
121	// 请求拟分配作业号 2，默认记录文件已属于作业 1——提交必须返回空作业与
122	// ErrRecordFileNameOccupied，不产生任何副作用，也不改动占用文件。
123	func TestSubmitRejectsWhenDefaultRecordFileNameOccupied(t *testing.T) {
124		dir := t.TempDir()
125		occupiedName := jobFileName(2)
126		old := succeededRecordInFile(t, 1, "alice", "old-req", []int64{6}, restoredOccupiedBase)
127		writeNamedSyntheticRecord(t, dir, occupiedName, old)
128	
129		s, err := Open(dir)
130		if err != nil {
131			t.Fatalf("目录本身没有重复作业号，单份非默认命名记录必须正常打开：%v", err)
132		}
133		t.Cleanup(func() { _ = s.Close() })
134	
135		g1, err := s.Get(1)
136		if err != nil {
137			t.Fatal(err)
138		}
139		if g1.Status != StatusSucceeded || g1.Archive == nil || g1.Archive.Sum != 6 {
140			t.Fatalf("作业 1 应按记录内容正常恢复：%+v", g1)
141		}
142		// 作业号由记录内容识别，文件名中的 2 不代表作业 2。
143		if _, err := s.Get(2); !errors.Is(err, ErrNotFound) {
144			t.Fatalf("文件名中的数字不能充当作业号：Get(2)=%v", err)
145		}
146		if _, err := os.Stat(filepath.Join(dir, jobFileName(1))); !errors.Is(err, os.ErrNotExist) {
147			t.Fatalf("打开归档不得为作业 1 补写默认命名副本：%v", err)
148		}
149	
150		before, err := os.ReadFile(filepath.Join(dir, occupiedName))
151		if err != nil {
152			t.Fatal(err)
153		}
154	
155		req := SubmitRequest{Submitter: "bob", RequestID: "new-req", Values: []int64{7}}
156		assertSubmitBlockedByOccupiedFile(t, s, req, 2, 1, occupiedName)
157		assertNewRequestLeftNoTrace(t, s, dir, req, 2, 1, 1)
158	
159		// 占用名称的旧记录逐字节不变，旧作业的成功归档继续可读。
160		after, err := os.ReadFile(filepath.Join(dir, occupiedName))
161		if err != nil {
162			t.Fatal(err)
163		}
164		if string(after) != string(before) {
165			t.Fatalf("被拒绝提交不得改写占用名称的旧记录：\nbefore=%s\nafter=%s", before, after)
166		}
167		g1Again, _ := s.Get(1)
168		if g1Again.Status != StatusSucceeded || g1Again.Archive == nil ||
169			g1Again.Archive.Sum != 6 || g1Again.Archive.SumOfSquares != 36 ||
170			g1Again.Archive.Checksum != g1.Archive.Checksum {
171			t.Fatalf("旧作业的状态、结果与校验值不得因拒绝而改变：%+v", g1Again)
172		}
173	
174		// 占用未解除前，同样的新请求（以及空请求号的新请求）继续被同一错误拒绝，
175		// 作业号始终未被消耗。
176		assertSubmitBlockedByOccupiedFile(t, s, req, 2, 1, occupiedName)
177		emptyReq := SubmitRequest{Submitter: "bob", Values: []int64{8}}
178		assertSubmitBlockedByOccupiedFile(t, s, emptyReq, 2, 1, occupiedName)
179		assertNewRequestLeftNoTrace(t, s, dir, req, 2, 1, 1)
180	}
