182	// TestSubmitFileNameOccupiedEvenWhenOccupierFailedOrCanceled 占用文件的旧记录
183	// 即使处于失败或取消终态，也不能被当作可覆盖的空位。
184	func TestSubmitFileNameOccupiedEvenWhenOccupierFailedOrCanceled(t *testing.T) {
185		cases := []struct {
186			name   string
187			status Status
188			reason string
189		}{
190			{name: "占用记录已失败", status: StatusFailed, reason: "平方和超出有符号 64 位整数范围"},
191			{name: "占用记录已取消", status: StatusCanceled, reason: ""},
192		}
193		for _, tc := range cases {
194			t.Run(tc.name, func(t *testing.T) {
195				dir := t.TempDir()
196				occupiedName := jobFileName(2)
197				j := &storedJob{
198					id: 1, submitter: "a", values: []int64{6},
199					queuedAt: restoredOccupiedBase, finishedAt: restoredOccupiedBase.Add(time.Second),
200					status: tc.status, failureReason: tc.reason,
201				}
202				writeNamedSyntheticRecord(t, dir, occupiedName, j)
203	
204				s, err := Open(dir)
205				if err != nil {
206					t.Fatalf("单份非默认命名记录必须正常打开：%v", err)
207				}
208				t.Cleanup(func() { _ = s.Close() })
209	
210				before, err := os.ReadFile(filepath.Join(dir, occupiedName))
211				if err != nil {
212					t.Fatal(err)
213				}
214				req := SubmitRequest{Submitter: "b", RequestID: "r", Values: []int64{1}}
215				assertSubmitBlockedByOccupiedFile(t, s, req, 2, 1, occupiedName)
216				assertNewRequestLeftNoTrace(t, s, dir, req, 2, 1, 1)
217				after, _ := os.ReadFile(filepath.Join(dir, occupiedName))
218				if string(after) != string(before) {
219					t.Fatalf("终态占用记录不得被被拒绝提交改写：\nbefore=%s\nafter=%s", before, after)
220				}
221				g, _ := s.Get(1)
222				if g.Status != tc.status {
223					t.Fatalf("旧作业状态必须保持 %s，got %s", tc.status, g.Status)
224				}
225			})
226		}
227	}
