229	// TestSubmitFileNameOccupiedDoesNotOverrideIdempotency 文件名冲突只影响需要
230	// 创建记录的新请求：命中已接受作业的幂等重放与幂等冲突优先，不被文件名占用
231	// 错误替代。
232	func TestSubmitFileNameOccupiedDoesNotOverrideIdempotency(t *testing.T) {
233		dir := t.TempDir()
234		occupiedName := jobFileName(2)
235		old := succeededRecordInFile(t, 1, "alice", "r1", []int64{6}, restoredOccupiedBase)
236		writeNamedSyntheticRecord(t, dir, occupiedName, old)
237	
238		s, err := Open(dir)
239		if err != nil {
240			t.Fatal(err)
241		}
242		t.Cleanup(func() { _ = s.Close() })
243		before, _ := os.ReadFile(filepath.Join(dir, occupiedName))
244	
245		// 同一提交人+非空请求号+相同内容：返回原作业当前详情，无错误。
246		replay := SubmitRequest{Submitter: "alice", RequestID: "r1", Values: []int64{6}}
247		j, err := s.Submit(replay)
248		if err != nil || j == nil || j.ID != 1 || j.Status != StatusSucceeded {
249			t.Fatalf("幂等重放必须优先于文件名占用检查：job=%+v err=%v", j, err)
250		}
251		if j.Archive == nil || j.Archive.Sum != 6 {
252			t.Fatalf("幂等重放应返回原作业当前详情：%+v", j)
253		}
254	
255		// 同一提交人+请求号但内容不同：仍是原有的幂等冲突（同时返回原作业），
256		// 不能被文件名占用错误替代。
257		conflictReq := SubmitRequest{Submitter: "alice", RequestID: "r1", Values: []int64{6, 7}}
258		cj, err := s.Submit(conflictReq)
259		if !errors.Is(err, ErrIdempotencyConflict) {
260			t.Fatalf("内容不同应返回幂等冲突，got %v", err)
261		}
262		if errors.Is(err, ErrRecordFileNameOccupied) {
263			t.Fatalf("幂等冲突不得被文件名占用错误替代：%v", err)
264		}
265		if cj == nil || cj.ID != 1 {
266			t.Fatalf("幂等冲突仍须返回原作业视图：%+v", cj)
267		}
268	
269		// 原记录字节不变；新作业号仍未消耗。
270		after, _ := os.ReadFile(filepath.Join(dir, occupiedName))
271		if string(after) != string(before) {
272			t.Fatal("幂等重放/冲突不得改写占用文件")
273		}
274		s.mu.Lock()
275		nextID := s.nextID
276		s.mu.Unlock()
277		if nextID != 2 {
278			t.Fatalf("幂等路径不得消耗作业号：nextID=%d", nextID)
279		}
280	
281		// 同一提交人的另一请求号（新请求）仍被占用错误拦截；不同提交人的新请求
282		// 同样被拦截——占用判断与提交人无关。
283		assertSubmitBlockedByOccupiedFile(t, s,
284			SubmitRequest{Submitter: "alice", RequestID: "r2", Values: []int64{1}}, 2, 1, occupiedName)
285		assertSubmitBlockedByOccupiedFile(t, s,
286			SubmitRequest{Submitter: "carol", RequestID: "r3", Values: []int64{1}}, 2, 1, occupiedName)
287	}
