289	// TestSubmitFileNameCollisionResolvedByRenamingAfterClose 关闭归档后把占用
290	// 名称的旧记录改名为另一个合法且不冲突的文件名，再打开归档：此前被拒绝的
291	// 请求作为新请求接受，取得原本未消耗的下一个作业号（2），按正常规则计算与
292	// 归档；旧作业仍使用它被读取时的文件名，新作业使用默认命名。
293	func TestSubmitFileNameCollisionResolvedByRenamingAfterClose(t *testing.T) {
294		dir := t.TempDir()
295		occupiedName := jobFileName(2)
296		// 作业 1 是排队记录：首次打开后会在占用文件中原地完成，验证恢复作业的
297		// 状态更新确实写回读入时的文件。
298		writeNamedSyntheticRecord(t, dir, occupiedName,
299			queuedStoredJob(1, "alice", []int64{6}, restoredOccupiedBase))
300	
301		s1, err := Open(dir)
302		if err != nil {
303			t.Fatal(err)
304		}
305		old := waitStatus(t, s1, 1, StatusSucceeded)
306		if old.Archive == nil || old.Archive.Sum != 6 {
307			t.Fatalf("作业 1 应在占用文件中正常完成：%+v", old)
308		}
309		assertNoDefaultRecord(t, dir, 1)
310		before, _ := os.ReadFile(filepath.Join(dir, occupiedName))
311	
312		req := SubmitRequest{Submitter: "carol", RequestID: "new-req", Values: []int64{7}}
313		assertSubmitBlockedByOccupiedFile(t, s1, req, 2, 1, occupiedName)
314		assertNewRequestLeftNoTrace(t, s1, dir, req, 2, 1, 1)
315		after, _ := os.ReadFile(filepath.Join(dir, occupiedName))
316		if string(after) != string(before) {
317			t.Fatal("被拒绝的提交不得改写占用名称的旧记录")
318		}
319		if err := s1.Close(); err != nil {
320			t.Fatal(err)
321		}
322	
323		// 关闭后由调用方把占用记录改名为另一个合法（job- 开头、.json 结尾）且
324		// 不与下一个默认文件名冲突的名称。
325		relocated := suffixedRecordName(1) // job-1-saved.json
326		if err := os.Rename(filepath.Join(dir, occupiedName), filepath.Join(dir, relocated)); err != nil {
327			t.Fatal(err)
328		}
329	
330		s2, err := Open(dir)
331		if err != nil {
332			t.Fatalf("改名后归档应正常打开：%v", err)
333		}
334		t.Cleanup(func() { _ = s2.Close() })
335	
336		// 旧作业从新读入的文件恢复，参数、状态与已有结果不变。
337		g1, err := s2.Get(1)
338		if err != nil {
339			t.Fatal(err)
340		}
341		if g1.Status != StatusSucceeded || g1.Archive == nil || g1.Archive.Sum != 6 ||
342			g1.Archive.Checksum != old.Archive.Checksum {
343			t.Fatalf("改名恢复后旧作业结果应原样可读：%+v", g1)
344		}
345	
346		// 此前被拒绝的请求现在作为新请求接受，取得原本未消耗的作业号 2。
347		j2, err := s2.Submit(req)
348		if err != nil {
349			t.Fatalf("冲突解除后被拒绝的请求应能作为新请求接受：%v", err)
350		}
351		if j2 == nil || j2.ID != 2 {
352			t.Fatalf("新作业应取得未消耗的下一个作业号 2：%+v", j2)
353		}
354		done := waitStatus(t, s2, 2, StatusSucceeded)
355		if done.Archive == nil || done.Archive.Sum != 7 || done.Archive.SumOfSquares != 49 {
356			t.Fatalf("新作业应按正常规则计算归档：%+v", done)
357		}
358	
359		// 新作业使用默认命名且记录内容中的作业号为 2；旧作业保持改名后的文件，
360		// 系统没有补出任何默认命名的作业 1 副本，也没有重复记录。
361		newData, err := os.ReadFile(filepath.Join(dir, jobFileName(2)))
362		if err != nil {
363			t.Fatal(err)
364		}
365		if !strings.Contains(string(newData), `"id": 2`) ||
366			!strings.Contains(string(newData), `"status": "succeeded"`) {
367			t.Fatalf("默认命名文件应保存新作业 2：\n%s", newData)
368		}
369		oldData, err := os.ReadFile(filepath.Join(dir, relocated))
370		if err != nil {
371			t.Fatal(err)
372		}
373		if !strings.Contains(string(oldData), `"id": 1`) ||
374			!strings.Contains(string(oldData), `"status": "succeeded"`) {
375			t.Fatalf("旧作业应仍在它被读取时的文件中：\n%s", oldData)
376		}
377		assertNoDefaultRecord(t, dir, 1)
378		if countJobFiles(t, dir) != 2 || countTmpFiles(t, dir) != 0 {
379			t.Fatalf("目录应恰好包含两份正式记录：files=%d tmps=%d",
380				countJobFiles(t, dir), countTmpFiles(t, dir))
381		}
382		if err := s2.Close(); err != nil {
383			t.Fatal(err)
384		}
385	
386		// 再次打开：没有重复作业号，两个作业都按记录内容正确恢复。
387		s3, err := Open(dir)
388		if err != nil {
389			t.Fatalf("改名并接受新作业后应正常重开：%v", err)
390		}
391		defer s3.Close()
392		r1, _ := s3.Get(1)
393		r2, _ := s3.Get(2)
394		if r1.Archive == nil || r1.Archive.Sum != 6 {
395			t.Fatalf("重开后作业 1 结果应保留：%+v", r1)
396		}
397		if r2.Archive == nil || r2.Archive.Sum != 7 {
398			t.Fatalf("重开后作业 2 结果应保留：%+v", r2)
399		}
400		l1, _ := s3.List("alice", time.Time{}, time.Time{})
401		l2, _ := s3.List("carol", time.Time{}, time.Time{})
402		if len(l1) != 1 || l1[0].ID != 1 || len(l2) != 1 || l2[0].ID != 2 {
403			t.Fatalf("按提交人列举应只看到各自的作业：alice=%v carol=%v", ids(l1), ids(l2))
404		}
405	}
406	
407	// TestNonCollidingNonDefaultFileNameDoesNotAffectSubmit 合法的非默认文件名
408	// 只要不与新作业的默认文件名冲突，就不影响打开与提交；作业号始终由记录内容
409	// 决定，而不是文件名中的数字（作业 1 保存在 job-...0007.json 中，下一个作业
410	// 仍是 2 而不是 8）。
411	func TestNonCollidingNonDefaultFileNameDoesNotAffectSubmit(t *testing.T) {
412		dir := t.TempDir()
413		nonDefault := jobFileName(7) // 文件名带 7，内容是作业 1
414		old := succeededRecordInFile(t, 1, "alice", "", []int64{6}, restoredOccupiedBase)
415		writeNamedSyntheticRecord(t, dir, nonDefault, old)
416	
417		s, err := Open(dir)
418		if err != nil {
419			t.Fatalf("合法非默认文件名不得阻止打开：%v", err)
420		}
421		t.Cleanup(func() { _ = s.Close() })
422	
423		if _, err := s.Get(7); !errors.Is(err, ErrNotFound) {
424			t.Fatalf("文件名中的 7 不能充当作业号：%v", err)
425		}
426		g1, _ := s.Get(1)
427		if g1.Status != StatusSucceeded || g1.Archive == nil || g1.Archive.Sum != 6 {
428			t.Fatalf("作业 1 应按记录内容恢复：%+v", g1)
429		}
430	
431		j2, err := s.Submit(SubmitRequest{Submitter: "bob", RequestID: "r", Values: []int64{2}})
432		if err != nil {
433			t.Fatalf("不冲突的非默认文件名不得影响新提交：%v", err)
434		}
435		if j2.ID != 2 {
436			t.Fatalf("作业号必须按记录内容续号为 2，got %d", j2.ID)
437		}
438		done := waitStatus(t, s, 2, StatusSucceeded)
439		if done.Archive.Sum != 2 {
440			t.Fatalf("新作业应正常计算：%+v", done)
441		}
442	
443		// 旧作业仍只在非默认文件中，新作业在默认命名文件中，各一份。
444		if countJobFiles(t, dir) != 2 {
445			t.Fatalf("目录应恰好有两份正式记录：%d", countJobFiles(t, dir))
446		}
447		assertNoDefaultRecord(t, dir, 1)
448		oldData, err := os.ReadFile(filepath.Join(dir, nonDefault))
449		if err != nil {
450			t.Fatal(err)
451		}
452		if !strings.Contains(string(oldData), `"id": 1`) {
453			t.Fatalf("非默认文件应继续只保存作业 1：\n%s", oldData)
454		}
455		newData, err := os.ReadFile(filepath.Join(dir, jobFileName(2)))
456		if err != nil {
457			t.Fatal(err)
458		}
459		if !strings.Contains(string(newData), `"id": 2`) {
460			t.Fatalf("默认命名文件应保存新作业 2：\n%s", newData)
461		}
