import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// failArchiveWrite 注入一个只让指定作业“成功归档”那一次落盘失败的故障：
// 该作业以 succeeded 状态（携带归档）保存时返回错误，模拟无法创建临时记录或
